  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://beecee.com/pages/faq', 'official_site', 'affiliate', 'The same FAQ describes the Rec Club: 25% commission on sales through a creator''s link, 15% on subscription renewals from October 1, 2026, a $50 bonus for every 10th sale, a 90-day cookie, no follower minimum, applications via Superfiliate, and an explicit statement that the program is not an MLM. The support email support@beecee.com is published on the page.', 'verified', now());
