  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Mist Ambassador Program', 'https://mistlebanon.com/become-our-partner/', 'https://mistlebanon.com/become-our-partner/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mistlebanon.com/become-our-partner/', 'official_site', 'affiliate_program', 'Mist''s own ambassador page states the program terms: 10% commission on every delivered order placed with the ambassador''s personal code, a 10% follower discount, free first bags, 50% off showcase bags, a 6-month term, and monthly payouts by the 10th via Whish Money, OMT or bank transfer.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mistlebanon.com/become-our-partner/', 'official_site', 'commission_cap', 'The brand''s own program page states ''No cap on earnings'' in its headline terms and repeats ''No cap'' in the commission section (''Your commission — On every delivered order your code brings in. No cap.''), so commission_cap is recorded as uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mistlebanon.com/become-our-partner/', 'official_site', 'ugc_collab', 'The page is built for content creators: ambassadors post Mist bags on their own terms with no minimum posting, sales are tracked live in the Mist app, and Mist may reshare ambassador content with credit during the term.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mistlebanon.com/become-our-partner/', 'official_site', 'general', 'Program terms state Lebanese law applies and Beirut courts decide disputes, and payouts are made in US dollars — a small, Lebanon-based brand running the program directly rather than through a network.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 14, 10, 8, 3, '{"compensation": "Published 10% commission on the brand''s own page with an explicit no-cap statement, plus free product and 50% off showcase bags \u2014 strong, fully published terms for a small brand.", "contact_access": "A public application form on the brand''s own program page; no email is published, so contact stays mid-range.", "credibility": "Small Lebanon-based DTC bag brand with its own store and app; limited third-party footprint, so credibility is scored conservatively.", "niche_fit": "Women''s handbags are a core fashion-accessory UGC niche, and the program is designed around creator codes and social posting.", "opportunity_availability": "Applications are publicly open on the brand''s site and reviewed individually; no follower minimum is stated.", "ugc_evidence": "A formal ambassador program with free product, live in-app sales tracking and brand resharing of ambassador content \u2014 clear, structured creator collaboration."}'::jsonb);
