  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://iflytravelpartners.au/faq/', 'official_site', 'affiliate_program', 'The FAQ states partners earn a percentage of the value of every ticket sold via their affiliate site, with a worked example: at an average flight of $2000 AUD the commission would be $20 (implying roughly 1%, though no headline rate is published — so commission_rate is null). Approved partners get a dashboard login, and the program is managed with OSI Affiliate.', 'verified', now());
