  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Creative Affiliate Program (Brand direct)', 'https://us.creative.com/affiliate/html/join-program.html?v=11', 'https://us.creative.com/affiliate/html/terms.html', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.creative.com/affiliate/html/terms.html', 'official_program_terms', 'affiliate', 'Creative''s own published programme terms (Creative Labs, Inc.) state affiliates enrol for an account on creative.com and earn a tiered percentage of net sales revenue: Special Products pay 8% on the first $999.99 per quarter, 10% on the next $4,000 and 12% above $4,999.99, while Other Products pay 3%; withdrawals require a $50 minimum. Because the rate is a tiered structure rather than a single rate, commission_rate is recorded as null with the tiers documented here.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.creative.com/affiliate/html/join-program.html?v=11', 'official_program_page', 'ugc_collab', 'Creative''s own join page offers an ''I am an influencer'' sign-up path where creators register with their website/handle and receive a unique affiliate link/coupon code. No earnings-cap statement and no absolute creator-count evidence appears in any fetched source, so commission_cap and creator_saturation are recorded as unknown rather than assumed.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 11, 7, 9, 5, '{"compensation": "Tiered published terms: 3% on other products, rising to 8\u201312% on special products by quarterly volume.", "contact_access": "Direct enrolment on the brand''s own site; no public partnerships email published.", "credibility": "Sound Blaster heritage brand selling direct in the US for decades.", "niche_fit": "Gaming and desktop audio is core creator-review territory.", "opportunity_availability": "Open self-serve registration on creative.com under published terms.", "ugc_evidence": "The brand''s own join page has a dedicated influencer path with a personal affiliate code."}'::jsonb);
